import subprocess, json
from datetime import datetime, timedelta

def get_product(pid):
    cmd = f'mcp-tool call woocommerce woo_products_get \'{{"productId": {pid}}}\''
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    lines = result.stdout.strip().split('\n')
    json_str = None
    for i, line in enumerate(lines):
        if line.startswith('{'):
            json_str = '\n'.join(lines[i:])
            break
    if json_str:
        try:
            return json.loads(json_str)
        except:
            return None
    return None

products = []
for pid in range(1, 41):
    p = get_product(pid)
    if p:
        sales_30 = 0
        for m in p.get('meta_data', []):
            if m['key'] == 'sales_last_30_days':
                sales_30 = int(m['value'])
        products.append({
            'id': p['id'],
            'name': p['name'],
            'date_created': p['date_created'],
            'stock_status': p['stock_status'],
            'sales_30': sales_30,
            'regular_price': p.get('regular_price',''),
            'price': p.get('price',''),
        })
    else:
        break

now = datetime(2026, 8, 2)
cutoff_90 = now - timedelta(days=90)

qualifying = []
for p in products:
    dc = datetime.fromisoformat(p['date_created'])
    days = (now - dc).days
    over_90 = days > 90
    low_sales = p['sales_30'] < 10
    qual = over_90 and low_sales
    if qual:
        qualifying.append(p)
    if low_sales or over_90:
        print(f"  ID {p['id']}: {p['name']:<25} days={days:>4} sales30={p['sales_30']:>5} over90={over_90} low_sales={low_sales}")

print(f"\nQualifying (both conditions): {len(qualifying)}")
for p in qualifying:
    dc = datetime.fromisoformat(p['date_created'])
    days = (now - dc).days
    print(f"  ID {p['id']}: {p['name']} (days={days}, sales={p['sales_30']}, price={p['price']}, regular={p['regular_price']})")
PYEOF

